const e="shaldon-carnival-fancy-dress",d=2025,t="Built from the undated Fancy Dress entry form and rules PDF on the carnival's website; no edition year is printed (the year field is only a placeholder). The document prints no fee, no date of the carnival, no contact, no criteria, no points and no theme. It prints a parent or guardian address and telephone line on the disclaimer form; these are blank fields and are not copied.",a={Title:"Rules & Criteria",Subtitle:"Fancy Dress Competition, Shaldon Water Carnival (UK)",NoticeTitle:"Please Read Before Registering",Notice:"Assembly at {{AssemblyTime}} at Shaldon Primary School. Judging at {{JudgingTime}}. Completed and signed forms must be handed in before judging starts.",Notes:["Parade from the school to the beach at {{ParadeTime}}.","Prize giving on the beach at {{PrizeTime}}.","Further information about the competition is on the website and in the carnival programme."],Sections:[{Key:"general",Title:"General",Items:["The fancy dress competition has five classes: Under 5 years; girls and boys 5-7 years; girls and boys 8 years and over; Open Pairs; and Groups of all ages.","Judging takes place before the procession.","The judges' decision is final."]},{Key:"eligibility",Title:"Eligibility",Items:["The competition is open to any age within the classes stated.","Class 1: under 5 years. Class 2: girls and boys 5-7 years. Class 3: girls and boys 8 years and over. Class 4: Open Pairs. Class 5: Groups, all ages.","All entrants take part at their own risk and must complete and sign the SWC Disclaimer.","For any entrant under 18, a parent or guardian must sign the disclaimer form."]},{Key:"registration",Title:"How to Register",Items:["There are two ways to register: print and complete the entry form and bring it on the day, or go to the Committee Tent on the beach on the day and fill in an entry form.","The form asks for the title of the entry, the names of the participants and the class entered. The committee issues an entrant number.","Completed and signed forms must be handed to a member of the committee at Shaldon Primary School before judging starts at {{JudgingTime}}.","Meet at the school at the assembly time to make sure you are registered to be included in the judging.","The disclaimer is available to print from the Forms page of the website or from the Committee Tent on the day."]},{Key:"dates",Title:"Times on the Day",Items:["Assembly time: {{AssemblyTime}}.","Judging time: {{JudgingTime}}.","Parade from the school to the beach: {{ParadeTime}}.","Prize giving on the beach: {{PrizeTime}}."]},{Key:"venue",Title:"Venue",Items:["Assembly and judging take place at {{SchoolVenue}}. The parade goes from the school to the beach."]},{Key:"conduct",Title:"Conduct and Disclaimer",Items:["To the fullest extent permitted by law, the committee accepts no liability for any injury, loss or damage caused during or after a participant takes part in the event.","The committee accepts no liability for any third party claims connected with the event.","Photographs will be taken at the event and may be used in advertising. By signing the form the entrant agrees to these rules."]},{Key:"judging",Title:"Judging",Items:["The judges' decision is final."]},{Key:"prizes",Title:"Prizes",Items:["Prizes are given for 1st, 2nd and 3rd in each class.","Prize giving is on the beach at {{PrizeTime}}."]}],Documents:[{Title:"Fancy Dress entry form and rules",Url:"https://shaldonwatercarnival.co.uk/uploads/1/2/8/2/12824711/fancy_dress_entry_form_and_rules.pdf"}]},n=[],s=[],i=[{Title:"Fancy Dress",Source:"Fancy Dress Competition Entry Form and Rules",Sections:{About:["Five classes: under 5 years; girls and boys 5-7 years; girls and boys 8 years and over; Open Pairs; Groups of all ages."],TimeAndFormat:null,Rules:["Write the title of the entry, the names of the participants and the class entered on the form."],Allowed:null,NotAllowed:null,Judging:["Judging is before the procession. The judges' decision is final."],Points:["Prizes are given for 1st, 2nd and 3rd in each class."],Notes:null},Markdown:`## About this competition
- Five classes: under 5 years; girls and boys 5-7 years; girls and boys 8 years and over; Open Pairs; Groups of all ages.

## Rules
- Write the title of the entry, the names of the participants and the class entered on the form.

## Judging
- Judging is before the procession. The judges' decision is final.

## Points
- Prizes are given for 1st, 2nd and 3rd in each class.`}],r=[],o=[{Key:"AssemblyTime",Kind:"time",Label:"Assembly time",Value:"12.30pm",Source:"Fancy Dress Competition Entry Form and Rules"},{Key:"JudgingTime",Kind:"time",Label:"Judging time",Value:"1pm",Source:"Fancy Dress Competition Entry Form and Rules"},{Key:"ParadeTime",Kind:"time",Label:"Parade time",Value:"1.30pm",Source:"Fancy Dress Competition Entry Form and Rules"},{Key:"PrizeTime",Kind:"time",Label:"Prize giving time",Value:"2pm",Source:"Fancy Dress Competition Entry Form and Rules"},{Key:"SchoolVenue",Kind:"address",Label:"Assembly venue",Value:{Name:"Shaldon Primary School",Address:"",City:"Shaldon",MapUrl:"",Directions:"The parade goes from the school to the beach; entries can also be made at the Committee Tent on the beach"},Source:"Fancy Dress Competition Entry Form and Rules"},{Key:"CarnivalWebsite",Kind:"link",Label:"Carnival website",Value:"www.shaldonwatercarnival.co.uk",Source:"Fancy Dress Competition Entry Form and Rules"}],l=[{Claim:"Classes, entry, times, disclaimer and prizes as printed.",SourceType:"Primary - organiser's own circular",Source:"Fancy Dress Competition Entry Form and Rules",Url:"https://shaldonwatercarnival.co.uk/uploads/1/2/8/2/12824711/fancy_dress_entry_form_and_rules.pdf"}],m={TemplateKey:e,Year:2025,Note:t,Page:a,ParticipantTypes:n,AgeGroups:s,Competitions:i,CompetitionAgeGroups:r,Variables:o,Evidence:l};export{s as AgeGroups,r as CompetitionAgeGroups,i as Competitions,l as Evidence,t as Note,a as Page,n as ParticipantTypes,e as TemplateKey,o as Variables,d as Year,m as default};
